class Solution {
  public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;
    for (int num : nums) {
      int lo = 0, hi = size;
      while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (tails[mid] < num) {
          lo = mid + 1;
        } else {
          hi = mid;
        }
      }
      tails[lo] = num;
      if (lo == size) {
        size++;
      }
    }
    return size;
  }
}

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = []
        for num in nums:
            i = bisect_left(tails, num)
            if i == len(tails):
                tails.append(num)
            else:
                tails[i] = num
        return len(tails)

impl Solution {
  pub fn length_of_lis(nums: Vec<i32>) -> i32 {
    let mut tails: Vec<i32> = Vec::new();
    for num in nums {
      match tails.binary_search(&num) {
        Ok(i) => tails[i] = num,
        Err(i) => {
          if i == tails.len() {
            tails.push(num);
          } else {
            tails[i] = num;
          }
        }
      }
    }
    tails.len() as i32
  }
}

const lengthOfLIS = (nums: number[]): number => {
  const tails: number[] = [];
  for (const num of nums) {
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < num) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    if (lo === tails.length) tails.push(num);
    else tails[lo] = num;
  }
  return tails.length;
};
